file.content:
            raw[name] = None
        except OSError as exc:
            raise Unreadable("%s: cannot read %s: %s" % (name, path, exc.strerror or exc))
    return raw


def decode(raw: Dict[str, Optional[bytes]]) -> Dict[str, str]:
    texts = {}
    for name, data in raw.items():
        if data is None:
            texts[name] = ""
            continue
        try:
            texts[name] = data.decode("utf-8")
        except UnicodeDecodeError:
            raise Unreadable("%s: not valid UTF-8" % name)
    return texts


class Data:
    def __init__(self, args: Args) -> None:
        names = COMMANDS[args.command][0]
        self.directory = args.directory
        self.raw = read_files(args.directory, names)
        self.text = decode(self.raw)
        self.catalog = self._parse(CATALOG, lambda t: parse_catalog(t))
        self.movements = []  # type: list
        self.orders = []  # type: List[Order]
        if MOVEMENTS in self.text:
            self.movements = self._parse(MOVEMENTS, lambda t: parse_movements(t, self.catalog))
        if ORDERS in self.text:
            self.orders = self._parse(ORDERS, lambda t: parse_orders(t, self.catalog))

    def _parse(self, name, parser):
        try:
            return parser(self.text[name])
        except ParseError as exc:
            raise Refused("%s: %s" % (name, exc))

    def find_order(self, ident: str) -> Order:
        wanted = upper(ident)
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refused("unknown order '%s'" % ident)

    def append_movements(self, lines: List[str]) -> None:
        """Validate the file with ``lines`` added, then append them."""
        raw = self.raw.get(MOVEMENTS)
        prefix = "\n" if raw and not raw.endswith(b"\n") else ""
        addition = prefix + "".join(line + "\n" for line in lines)
        self._parse_movements_text(self.text[MOVEMENTS] + addition)
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab") as handle:
                handle.write(addition.encode("utf-8"))
        except OSError as exc:
            raise Unreadable("%s: cannot write %s: %s" % (MOVEMENTS, path, exc.strerror or exc))

    def _parse_movements_text(self, text: str) -> None:
        try:
            parse_movements(text, self.catalog)
        except ParseError as exc:
            raise Refused("%s: %s" % (MOVEMENTS, exc))


