class Result:
    def __init__(self, proc):
        self.code = proc.returncode
        self.out = proc.stdout.decode("utf-8")
        self.err = proc.stderr.decode("utf-8")


class CliCase(unittest.TestCase):
    catalog = CATALOG
    movements = MOVEMENTS
    orders = ORDERS

    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.dir, True)
        self.put("catalog.txt", self.catalog)
        self.put("movements.txt", self.movements)
        self.put("orders.txt", self.orders)

    def path(self, name):
        return os.path.join(self.dir, name)

    def put(self, name, content):
        if content is None:
            if os.path.exists(self.path(name)):
                os.remove(self.path(name))
            return
        data = content if isinstance(content, bytes) else content.encode("utf-8")
        with open(self.path(name), "wb") as handle:
            handle.write(data)

    def read(self, name):
        with open(self.path(name), "rb") as handle:
            return handle.read()

    def run_cli(self, *args, dir_first=False, cwd=None):
        env = dict(os.environ, PYTHONPATH=ROOT + os.pathsep + os.environ.get("PYTHONPATH", ""))
        argv = list(args)
        if not cwd and not any(a == "--dir" or a.startswith("--dir=") for a in argv):
            argv = ["--dir", self.dir] + argv if dir_first else argv + ["--dir", self.dir]
        proc = subprocess.run(
            [sys.executable, "-m", "stockroom"] + argv,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, cwd=cwd or ROOT,
        )
        return Result(proc)

    def ok(self, *args, **kw):
        r = self.run_cli(*args, **kw)
        self.assertEqual(r.code, 0, r.err)
        return r.out

    def refuse(self, code, *args, **kw):
        before = {n: self.read(n) for n in os.listdir(self.dir)}
        r = self.run_cli(*args, **kw)
        self.assertEqual(r.code, code, r.err)
        self.assertEqual(r.out, "", "stdout must be empty on failure")
        self.assertTrue(r.err.startswith("stockroom: "), r.err)
        after = {n: self.read(n) for n in os.listdir(self.dir)}
        self.assertEqual(before, after, "files must be unchanged")
        return r.err


class ShelvesTests(CliCase):
    def test_stock_text(self):
        self.assertEqual(
            self.ok("stock"),
            "AB-100 17 ok Garden gnome\nCD-205 40 low Seed packet, mix\nEF-310 0 out Gift voucher\n",
        )

    def test_stock_json(self):
        data = json.loads(self.ok("stock", "--json"))
        self.assertEqual(data[0], {"sku": "AB-100", "name": "Garden gnome", "onhand": 17, "status": "ok"})
        self.assertEqual([d["status"] for d in data], ["ok", "low", "out"])
        self.assertEqual(list(data[0]), ["sku", "name", "onhand", "status"])
        self.assertTrue(self.ok("stock", "--json").endswith("}\n]\n"))

    def test_json_not_ascii_escaped(self):
        self.put("catalog.txt", "AB-100 | Gnöme | 1 | 0\n")
        self.put("movements.txt", "2024-03-01 AB-100 +17\n")
        self.assertIn("Gnöme", self.ok("stock", "--json"))
        self.assertEqual(self.ok("stock"), "AB-100 17 ok Gnöme\n")

    def test_low_text_and_json(self):
        self.assertEqual(self.ok("low"), "CD-205 40 40 40\nEF-310 0 0 1\n")
        self.assertEqual(
            json.loads(self.ok("low", "--json")),
            [{"sku": "CD-205", "onhand": 40, "reorder": 40, "buy": 40},
             {"sku": "EF-310", "onhand": 0, "reorder": 0, "buy": 1}],
        )

    def test_empty_results(self):
        self.put("catalog.txt", "# nothing\n")
        self.put("movements.txt", None)
        self.put("orders.txt", None)
        self.assertEqual(self.ok("stock"), "")
        self.assertEqual(self.ok("stock", "--json"), "[]\n")
        self.assertEqual(self.ok("report"), "")
        self.assertEqual(self.ok("report", "--format", "json"), "[]\n")
        self.assertEqual(self.ok("report", "--format", "csv"), "order,date,customer,status,ordered,shipped,quoted,invoiced\n")

    def test_history(self):
        self.assertEqual(
            self.ok("history", "ab-100"),
            "2024-03-01 +20 20 first delivery\n2024-03-04 -3 17 order SO-1001\n",
        )
        self.assertEqual(self.ok("history", "EF-310"), "")
        self.assertEqual(self.ok("history", "EF-310", "--json"), "[]\n")
        self.assertEqual(
            json.loads(self.ok("history", "AB-100", "--json")),
            [{"date": "2024-03-01", "delta": "+20", "balance": 20, "note": "first delivery"},
             {"date": "2024-03-04", "delta": "-3", "balance": 17, "note": "order SO-1001"}],
        )
        self.assertEqual(json.loads(self.ok("history", "CD-205", "--json"))[0]["note"], "")
        self.assertEqual(self.ok("history", "CD-205"), "2024-03-05 +40 40\n")

    def test_history_in_counting_order(self):
        self.put("movements.txt", "2024-03-04 AB-100 -3\n2024-03-01 AB-100 +20\n")
        self.assertEqual(self.ok("history", "AB-100"), "2024-03-01 +20 20\n2024-03-04 -3 17\n")

    def test_history_unknown_sku_refused(self):
        self.assertIn("ZZ-999", self.refuse(1, "history", "ZZ-999"))
        self.refuse(1, "history", "nonsense")

    def test_receive_appends_and_prints(self):
        out = self.ok("receive", "2024-03-10", "ef-310", "5", "  new stock  ")
        self.assertEqual(out, "2024-03-10 EF-310 +5 new stock\n")
        self.assertEqual(self.read("movements.txt"), (MOVEMENTS + "2024-03-10 EF-310 +5 new stock\n").encode())

    def test_ship_without_note(self):
        self.assertEqual(self.ok("ship", "2024-03-10", "AB-100", "2"), "2024-03-10 AB-100 -2\n")
        self.assertTrue(self.read("movements.txt").endswith(b"2024-03-10 AB-100 -2\n"))

    def test_missing_final_newline_added(self):
        self.put("movements.txt", MOVEMENTS.rstrip("\n"))
        self.ok("receive", "2024-03-10", "AB-100", "1")
        self.assertEqual(self.read("movements.txt"), (MOVEMENTS + "2024-03-10 AB-100 +1\n").encode())

    def test_file_created_when_missing(self):
        self.put("movements.txt", None)
        self.assertEqual(self.ok("receive", "2024-03-10", "AB-100", "1"), "2024-03-10 AB-100 +1\n")
        self.assertEqual(self.read("movements.txt"), b"2024-03-10 AB-100 +1\n")

    def test_empty_file_no_leading_newline(self):
        self.put("movements.txt", "")
        self.ok("receive", "2024-03-10", "AB-100", "1")
        self.assertEqual(self.read("movements.txt"), b"2024-03-10 AB-100 +1\n")

    def test_crlf_file_stays_valid(self):
        self.put("movements.txt", MOVEMENTS.replace("\n", "\r\n"))
        self.ok("receive", "2024-03-10", "AB-100", "1")
